'use client';

import ProjectHeader from '@/components/project/ProjectHeader';
import { useRouter } from 'next/navigation';
import React from 'react';
import { useProjectId } from '@/hooks/useProjectId';

export default function ProjectsLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const [activeTab, setActiveTab] = React.useState('backlog');
  const { projectId, isValidProject } = useProjectId();
  const router = useRouter();

  const onTabChange = (tab: string) => {
    setActiveTab(tab);
  };

  if (!isValidProject) {
    return (
      <div className="border-b border-slate-700 bg-slate-900 px-6 py-4">
        <h1 className="text-2xl font-semibold text-white">Project Not Found</h1>
        <button
          onClick={() => router.push('/projects')}
          className="text-blue-500 hover:underline"
        >
          Go to Projects
        </button>
      </div>
    );
  }

  const [activeTab, setActiveTab] = React.useState('backlog');
  const { isValidProject } = useProjectId();
  const router = useRouter();

  const onTabChange = (tab: string) => {
    setActiveTab(tab);
  };

  if (!isValidProject) {
    return (
      <div className="border-b border-slate-700 bg-slate-900 px-6 py-4">
        <h1 className="text-2xl font-semibold text-white">Project Not Found</h1>
        <button
          onClick={() => router.push('/projects')}
          className="text-blue-500 hover:underline"
        >
          Go to Projects
        </button>
      </div>
    );
  }

  return (
    <div className="bg-slate-900">
      <ProjectHeader activeTab={activeTab} onTabChange={onTabChange} />
      {children}
    </div>
  );
}

import React from 'react';
import { useRouter } from 'next/navigation';
import { Lock, Plus } from 'lucide-react';
import Link from 'next/link';
import NewViewModal from './views/NewViewModal';
import { useProjectId } from '@/hooks/useProjectId';
import { useProjectStore } from '@/store/useProjectStore';

export default function ProjectHeader({
  activeTab,
  onTabChange,
}: ProjectHeaderProps) {
  const router = useRouter();
  const { projectId } = useProjectId();
  const { getCurrentProject } = useProjectStore();
  const [showNewViewModal, setShowNewViewModal] = React.useState(false);

  const handleCreateView = (viewName: string, viewType: string) => {
    console.log(`Creating view: ${viewName} of type ${viewType}`);
    setShowNewViewModal(false);
    onTabChange(`custom-${viewName.toLowerCase().replace(/\s+/g, '-')}`);
  };

  // Get current project from store
  const currentProject = getCurrentProject();

  // Fallback project name if project not found in store
  const getProjectName = (id: string | null) => {
    if (currentProject) {
      return currentProject.name;
    }

    // Fallback based on ID
    switch (id) {
      case 'task-flow':
        return 'Task Flow';
      case 'untitled-project':
        return "@nyambogahezron's untitled project";
      case 'quizfy-app':
        return 'quizfy-app';
      case 'default':
        return 'Default Project';
      default:
        return 'Task Flow';
    }
  };

  const projectName = getProjectName(projectId);

