/**
 * Drag and drop utilities for Kanban board using react-beautiful-dnd
 */

import { DropResult } from 'react-beautiful-dnd';

export interface KanbanColumn {
  id: string;
  title: string;
  status: 'Todo' | 'In Progress' | 'Done' | 'Next Version';
}

export const KANBAN_COLUMNS: KanbanColumn[] = [
  { id: 'todo', title: 'Todo', status: 'Todo' },
  { id: 'in-progress', title: 'In Progress', status: 'In Progress' },
  { id: 'done', title: 'Done', status: 'Done' },
  { id: 'next-version', title: 'Next Version', status: 'Next Version' },
];

export const handleDragEnd = (
  result: DropResult,
  onTaskMove: (taskId: string, newStatus: 'Todo' | 'In Progress' | 'Done' | 'Next Version') => void
) => {
  const { destination, source, draggableId } = result;

  // If dropped outside any droppable area
  if (!destination) {
    return;
  }

  // If dropped in the same position
  if (
    destination.droppableId === source.droppableId &&
    destination.index === source.index
  ) {
    return;
  }

  // Find the target column
  const targetColumn = KANBAN_COLUMNS.find(
    (col) => col.id === destination.droppableId
  );

  if (targetColumn) {
    // Extract task ID from draggableId (format: "task-{taskId}")
    const taskId = draggableId.replace('task-', '');
    onTaskMove(taskId, targetColumn.status);
  }
};

// Helper function to get column ID from status
export const getColumnIdFromStatus = (status: 'Todo' | 'In Progress' | 'Done' | 'Next Version'): string => {
  const column = KANBAN_COLUMNS.find(col => col.status === status);
  return column?.id || 'todo';
};

// Helper function to get status from column ID
export const getStatusFromColumnId = (columnId: string): 'Todo' | 'In Progress' | 'Done' | 'Next Version' => {
  const column = KANBAN_COLUMNS.find(col => col.id === columnId);
  return column?.status || 'Todo';
};

'use client';

import React from 'react';
import { DragDropContext, DropResult } from 'react-beautiful-dnd';
import KanbanColumn from '@/components/Kanban/KanbanColumn';
import useProjectStore from '@/store/useProjectStore';
import { handleDragEnd, KANBAN_COLUMNS } from '@/utils/dragAndDrop';

interface KanbanBoardProps {
	projectId: string;
}

export default function KanbanBoard({ projectId }: KanbanBoardProps) {
	const moveTask = useProjectStore((state) => state.moveTask);

	if (!projectId) return null;

	const onDragEnd = (result: DropResult) => {
		handleDragEnd(result, (taskId, newStatus) => {
			moveTask(taskId, newStatus);
		});
	};

	return (
		<DragDropContext onDragEnd={onDragEnd}>
			<div className='flex-1 p-6 bg-slate-900'>
				<div className='flex space-x-4 h-full'>
					{KANBAN_COLUMNS.map((column, index) => (
						<KanbanColumn
							key={column.id}
							title={column.title}
							projectId={projectId}
							status={column.status}
							columnId={column.id}
							description={getColumnDescription(column.status)}
							color={getColumnColor(index)}
						/>
					))}
				</div>
			</div>
		</DragDropContext>
	);
}

